export function celestialVisibility({altitudeDeg,cloudFraction=null,sunAltitudeDeg=null}={}){if(!Number.isFinite(altitudeDeg))return{state:'UNKNOWN'};if(altitudeDeg<=0)return{state:'BELOW_HORIZON'};const cloud=Number.isFinite(cloudFraction)?Math.max(0,Math.min(1,cloudFraction)):null;const daylight=Number.isFinite(sunAltitudeDeg)&&sunAltitudeDeg>-6;let state=daylight?'DAYLIGHT':cloud!=null&&cloud>0.7?'CLOUD_LIMITED':'VISIBLE_GEOMETRY';return{state,altitudeDeg,cloudFraction:cloud,rule:'GEOMETRIC_OR_WEATHER_VISIBILITY_NOT_PHOTOMETRIC_GUARANTEE'};}
